(async () => {
  const out = { path: location.pathname };
  out.detailTitle = document.querySelector('.pj-title')?.textContent || null;
  out.crumb = (document.querySelector('.pj-crumb')?.innerText || '').replace(/\s+/g, ' ');
  out.headActions = [...document.querySelectorAll('.pj-head-actions button')].map((b) => b.textContent.trim()).filter(Boolean).join(' | ');
  out.cards = document.querySelectorAll('.pj-card').length;
  return JSON.stringify(out);
})()
